  function log(s,tenantId,action,detail,type='运营'){s.logs.unshift({id:id('log'),tenantId,time:clock(),actor:'演示操作员',action,detail,type})}
  function requireRoom(s,tenantId,roomId){const r=s.rooms.find(x=>x.id===roomId&&x.tenantId===tenantId);if(!r)throw Error('当前商户无权访问该房间');return r}
  function checkIn(s,tenantId,roomId,form){const r=requireRoom(s,tenantId,roomId);if(!['vacant','reserved'].includes(r.status))throw Error('该房间当前不能办理入住');if(!form.name?.trim()||!/^1\d{10}$/.test(form.phone||''))throw Error('请填写姓名和11位手机号');if(!form.start||!form.end||form.end<form.start)throw Error('请检查租约起止日期');const rent=Math.round(Number(form.rent)*100),deposit=Math.round(Number(form.deposit)*100);if(!Number.isFinite(rent)||rent<=0||!Number.isFinite(deposit)||deposit<0)throw Error('请填写有效的租金和押金');Object.assign(r,{status:'occupied',resident:form.name.trim(),phone:form.phone,start:form.start,end:form.end,rent,deposit,grant:r.online?'已生效':'授权待同步'});s.bills.unshift({id:id('bill'),tenantId,roomId,period:'2026-10',kind:'房租',amount:rent,resident:r.resident,status:'unpaid',due:form.start,items:[{label:'首期房租',amount:rent}]});s.commands.unshift({id:id('cmd'),tenantId,roomId,action:'入住授权',status:r.online?'已确认':'待同步',time:clock()});log(s,tenantId,'办理入住',r.number+' · '+r.resident);return r}
